"pkglib.installAll.what": "Che cos'è «Installa tutto»?",
"pkglib.installAll.whatBody": "«Installa tutto» elabora in ordine ogni pacchetto pronto: gioco base → aggiornamenti → DLC. Se hai due aggiornamenti della stessa versione (o due DLC in conflitto), usa la casella su ogni riga per scegliere quale deve installare questa console: solo uno per gruppo. Deseleziona per escludere quel gruppo. Il pulsante Installa di una singola riga installa sempre e solo quel pacchetto.",
