fs_conflict_title: "\"{name}\" è già qui",
fs_conflict_body_file: "Sostituisci sovrascrive il file presente, e non si può annullare. Se si trova in un'immagine di gioco montata, un file difettoso può impedire l'avvio del gioco.",
fs_conflict_body_folder: "Unisci copia nella cartella presente: i file con lo stesso nome vengono sovrascritti, tutto il resto rimane com'è.",
fs_conflict_body_mixed: "Un file e una cartella non possono sostituirsi a vicenda. Saltalo, oppure tieni entrambi con un nuovo nome.",
