health_junk_explain_v2: "Cose che ps5upload ha creato e non servono più: file incompleti di trasferimenti interrotti, copie di pacchetti rimaste per più di un'ora nella sua cartella temporanea e vecchi file dei test di velocità. Vengono controllate solo le cartelle di ps5upload; i tuoi giochi, pacchetti e salvataggi non vengono mai toccati.",
