"speedtest.up": "Verso la PS5 (upload)",
"speedtest.uploading": "Invio alla PS5…",
"speedtest.verdict.gigabit": "È un collegamento gigabit pieno: veloce quanto consente la porta di rete della PS5.",
"speedtest.verdict.hundred": "Sembra un collegamento a 100 Mbit, che si ferma intorno a 11 MB/s. Controlla il cavo (usa Cat5e o superiore) e che ogni porta di switch o router lungo il percorso sia gigabit.",
"speedtest.verdict.mid": "Buono, ma sotto quello che dà un cavo gigabit (90–115 MB/s). Cause comuni: Wi-Fi su uno dei due lati o altro traffico sulla rete.",
"speedtest.verdict.slow": "Lento. Di solito la causa è un segnale Wi-Fi debole, una VPN o una rete occupata. La soluzione è un cavo di rete fino alla PS5.",
stop: "Interrompi",
activity_description_v2: "Tutto ciò che l'app sta facendo e ha fatto sulle tue console: caricamenti, download, installazioni e operazioni sui file. Da qui puoi interromperne o riprovarne una. Le ultime 100 vengono conservate, anche dopo un riavvio.",
disk_usage_description_v2: "Guarda che cosa occupa spazio sulla PS5. Ogni blocco è una cartella, grande quanto ciò che contiene; fai clic su una per guardarci dentro.",
fw_spoof_subtitle_v2: "Controlla se la versione del firmware dichiarata da questa PS5 è stata modificata da un payload di spoofing, così conosci la versione reale prima di installare qualcosa che ne dipende.",
health_subtitle_v2: "Controlla che la PS5, questa app e la rete tra loro funzionino, dice cosa sistemare quando qualcosa non va e misura quanto velocemente si spostano i file tra loro.",
localimage_subtitle_v2: "Apri un'immagine di gioco (.exfat o .ffpkg) che si trova su questo computer e aggiungi, sostituisci o rimuovi file al suo interno, senza estrarre l'intera immagine.",
processes_subtitle_v2: "I programmi in esecuzione sulla PS5 in questo momento. Puoi interromperne o riavviarne uno; attenzione ai processi di sistema, perché interrompere quello sbagliato può bloccare la console.",
remotePlay_subtitle_v2: "Configura questa PS5 per il Remote Play e ottieni il PIN che vi associa l'app PS Remote Play.",
saves_description_v2: "Dati di salvataggio sulla PS5, una voce per gioco. Salva i salvataggi di un gioco in un .zip su questo computer e ripristinali in seguito.",
shell_description_v2: "Digita comandi che vengono eseguiti sulla PS5, nel processo dell'helper. Per uso avanzato. L'output è limitato a 256 KB per comando; le frecce su e giù richiamano i comandi precedenti.",
"arcpkg.links.go": "Scarica {count} file",
"arcpkg.links.help": "Incolla il link diretto all'archivio, o a ogni parte di un archivio diviso, uno per riga. I file vengono scaricati su questo computer (Downloads/ps5upload), che deve avere spazio per tutti; poi i pacchetti al loro interno vengono estratti sulla PS5 come sopra.",
"arcpkg.links.kept": "{count} file scaricati si trovano in {dir}. Vengono conservati per poter riprovare l'installazione; eliminali quando hai finito.",
"arcpkg.links.progress": "Download del file {n} di {count} su questo computer…",
"arcpkg.links.title": "L'archivio è dietro link di download",
"arcpkg.noFirstPart": "I file sono stati scaricati, ma nessuno è la prima parte di un archivio (.zip, .7z, .rar o .part1.rar). Controlla i link.",
"convert_games.subtitle": "Trasforma una cartella o un'immagine di gioco in un pacchetto installabile (.pkg), oppure una cartella di gioco in un'immagine di gioco (.exfat, o la più piccola .ffpfsc) che ShadowMount+ monta. Il lavoro viene svolto su questo computer, non sulla console.",
convert_games_title: "Converti giochi",
"fpkg.image.done": "Immagine di gioco scritta e riletta. Copiala su un'unità della PS5 (Caricamento) e ShadowMount+ la monterà.",
"fpkg.image.what": "Un unico file da copiare su un'unità della PS5, che ShadowMount+ monta e mostra nella schermata iniziale. Non viene installato nulla.",
"fpkg.image.folderOnly": "Solo una cartella di gioco su questo computer può diventare un'immagine di gioco.",
