trace_what: "Per un'immagine di gioco LZ4 che carica come il gioco gioca. Una versione di misurazione di ampr_emu registra ogni file letto mentre giochi; un profilo costruito da quelle sessioni sceglie dimensioni dei blocchi, layout e cache per file invece di un'unica stima. Convert lo usa quando crei un'immagine LZ4 di questo gioco.",
