"collection.trash_unavailable_v2": "Questo motore non ha un cestino. Per eliminare copie da qui, attiva “Consenti l’eliminazione definitiva delle copie” in Collezione → Cartelle.",
"pkg.sony_80b21104": "La PS5 non ha accettato questo pacchetto (0x80B21104). Se altri pacchetti si installano su questa console, il problema è questo file: quasi sempre un gioco recente il cui pacchetto è stato creato con strumenti più nuovi di quanto il firmware di questa console comprenda, o un pacchetto che non è una build con firma falsa (FPKG). Usa un pacchetto fatto per il tuo firmware (un backport) o installa il gioco in un altro modo che salta l’installatore: copia la sua cartella di gioco, o un’immagine di gioco (.exfat o .ffpfsc) per ShadowMount+, con Caricamento.",
