err_launch_homebrew_refused: "La PS5 ha rifiutato di avviare questo titolo (0x80940033). Al momento la console non avvia homebrew né giochi da pacchetti fake: carica kstuff (oppure riavvia ed esegui di nuovo il jailbreak), poi riprova.",
"fakegame.fw.body": "Si installerà, ma i pacchetti di giochi fake PS5 non si possono giocare su firmware superiori a {last}. I pacchetti PS4 vanno bene e le app homebrew PS5 si avviano normalmente.",
"fakegame.fw.launch": "I pacchetti di giochi fake PS5 non si possono giocare su firmware superiori a {last} (questa console è su {fw}). Se questo gioco è stato installato da un pacchetto fake, è per questo che non si avvia. I pacchetti PS4 vanno bene.",
