"fakegame.fw.title": "Questo gioco PS5 si può installare ma non giocare sul FW {fw}",
first_run_helper_only: "Invia solo ps5upload",
first_run_helper_only_hint: "Carichi già kstuff da solo (un autoloader, etaHEN, elf-arsenal)? Invia solo ps5upload — caricare kstuff una seconda volta ne impila un'altra copia. I payload già in esecuzione vengono comunque saltati.",
