fs_progress_eta: "circa {time} rimanenti",
hardware_fan_lower_louder: "È la temperatura che il controllo delle ventole della console cerca di mantenere. Più bassa significa più rumorosa: sotto carico le ventole girano quanto serve per restarci. Mantenuta dopo i riavvii.",
