"install_help_what_means": "Cosa significa?",
"install_help_wont_launch": "Il gioco non si avvia?",
install_hint_setup_exe: "Il programma di installazione si è aperto: seguilo e aggiornerà PS5Upload sul posto.",
install_path_fallback_hint: "Un'ultima risorsa per un pacchetto già presente sulla PS5, quando la PS5 lo rifiuta dalla propria memoria e non riesce nemmeno a prenderlo da questo computer. Usata solo per un gioco base non installato, quindi non può rimuovere nulla. Non verificata: ha funzionato sul firmware 11.20 ed è rifiutata su 13.60. Se la provi, segnala per favore se ha funzionato.",
install_path_fallback_label: "Installa tramite percorso del file quando la PS5 non riesce a raggiungere questo computer",
"installed_fix_permissions": "Correggi permessi: rendi la cartella di questo gioco leggibile ed eseguibile dalla PS5 (chmod 777)",
"installed_fix_permissions_done": "Permessi corretti: ogni file nella cartella di questo gioco ora è 0777. Premi Gioca.",
"installed_fix_permissions_short": "Correggi permessi",
"installed_launch_homebrew_refused": "La PS5 ha rifiutato di avviare questo gioco (0x80940033). Al momento la console non avvia homebrew né giochi da pacchetti fake: ricarica kstuff (oppure riavvia ed esegui di nuovo il jailbreak), poi premi di nuovo Gioca.",
"installed_launch_no_kstuff": "La PS5 ha rifiutato di avviare questo gioco (0x80940033) perché kstuff non è in esecuzione. Senza di esso la console non avvia homebrew né giochi da pacchetti fake. Carica kstuff (con il tuo autoloader, oppure Connessione → Configura) e premi di nuovo Gioca.",
job_why_lanes: "Connessioni: {avg} in media, {max} al massimo; blocco {chunk}",
job_why_loading: "Caricamento…",
job_why_local_note: "Salvato solo su questo computer. Non contiene indirizzi né percorsi di file, e nulla viene inviato altrove.",
job_why_network: "Nessun limite singolo ha prevalso: né la console né l'origine hanno rallentato il lavoro, quindi il limite era il collegamento di rete.",
job_why_none: "Nessun riepilogo è stato registrato per questo lavoro.",
job_why_receiver_bound: "Limitato dalla console {pct} %: la console non riusciva ad accettare dati più velocemente di quanto permettessero la sua unità o i suoi worker.",
